// Input: items[0].json = your aggregated result
// Output: enriched summary object with insights for dashboard

const data = items[0].json;

function getTopKey(obj) {
  return Object.entries(obj).reduce((a, b) => a[1] > b[1] ? a : b)[0];
}

function getRate(numerator, denominator) {
  return ((numerator / denominator) * 100).toFixed(1) + "%";
}

// Extract data
const stepDropoffs = data.stepDropoffs || {};
const deviceDropoffs = data.deviceDropoffs || {};
const errorClusters = data.errorClusters || {};
const sessionDurationClusters = data.sessionDurationClusters || {};

// Total dropoffs
const totalDropoffs = Object.values(stepDropoffs).reduce((a,b) => a+b, 0);

// Step % drop-off
const stepDropoffPercent = {};
for (let step in stepDropoffs) {
  stepDropoffPercent[step] = getRate(stepDropoffs[step], totalDropoffs);
}

// Cumulative drop-offs
const cumulativeDropoffs = {};
let runningTotal = 0;
for (let step of Object.keys(stepDropoffs).sort((a,b)=>a-b)) {
  runningTotal += stepDropoffs[step];
  cumulativeDropoffs[step] = getRate(runningTotal, totalDropoffs);
}

// Step + device breakdown placeholder (requires raw user data if available)
const stepDeviceBreakdown = {}; // Example: {"1": {"mobile": 30, "desktop": 20, ...}}

// Step + error correlation placeholder (requires raw user data if available)
const stepErrorCorrelation = {}; // Example: {"1": {"connection_error": 5, "form_validation_error": 2, ...}}

// Average session duration estimate (weighted midpoint per cluster)
const sessionDurations = {"0-10s":5, "11-30s":20, "31-60s":45, "60s+":75};
let totalDuration = 0, totalSessions = 0;
for (let key in sessionDurationClusters) {
  const count = sessionDurationClusters[key];
  totalDuration += (sessionDurations[key] || 0) * count;
  totalSessions += count;
}
const avgSessionDuration = (totalDuration / (totalSessions || 1)).toFixed(1); // in seconds

// Identify top items
const topStep = getTopKey(stepDropoffs);
const worstDevice = getTopKey(deviceDropoffs);
const topError = getTopKey(errorClusters);

// Early quit rate = (11–30s + 31–60s) / total
const earlyQuit = (sessionDurationClusters["11-30s"] || 0) + (sessionDurationClusters["31-60s"] || 0);
const earlyQuitRate = getRate(earlyQuit, totalSessions);

// Prepare final enriched JSON
const enrichedJSON = {
  summary: {
    topStep: `Step ${topStep}`,
    worstDevice,
    topError,
    earlyQuitRate,
    totalDropoffs,
    avgSessionDuration: avgSessionDuration + "s"
  },
  details: {
    stepDropoffs,
    stepDropoffPercent,
    cumulativeDropoffs,
    deviceDropoffs,
    errorClusters,
    sessionDurationClusters,
    stepDeviceBreakdown,
    stepErrorCorrelation
  }
};

// Return as pretty JSON string in dropoffData
// Return enriched JSON as an object instead of string
return [
  {
    json: {
      dropoffData: JSON.stringify($json, null, 2) // pretty JSON string
    }
  }
];

const stepCounts = {};
const deviceCounts = {};
const errorClusters = {};
const durationBuckets = { "0-10s": 0, "11-30s": 0, "31-60s": 0, "60s+": 0 };

for (const item of items) {
  const { step_completed, device, error_event, session_duration } = item.json;

  // steps
  stepCounts[step_completed] = (stepCounts[step_completed] || 0) + 1;

  // devices
  deviceCounts[device] = (deviceCounts[device] || 0) + 1;

  // error messages
  if (error_event) {
    errorClusters[error_event] = (errorClusters[error_event] || 0) + 1;
  }

  // session duration bucket
  if (session_duration <= 10) durationBuckets["0-10s"]++;
  else if (session_duration <= 30) durationBuckets["11-30s"]++;
  else if (session_duration <= 60) durationBuckets["31-60s"]++;
  else durationBuckets["60s+"]++;
}

return [{
  json: {
    stepDropoffs: stepCounts,
    deviceDropoffs: deviceCounts,
    errorClusters,
    sessionDurationClusters: durationBuckets
  }
}];

// Get input text
let analysis = $json["Onboarding Analysis"];

// Replace **bold** with *bold* for Slack
analysis = analysis.replace(/\*\*(.*?)\*\*/g, '*$1*');

// Return Slack-friendly message
return {
  blocks: [
    {
      type: "header",
      text: {
        type: "plain_text",
        text: "📊 Onboarding Drop-off Analysis"
      }
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: analysis
      }
    }
  ],
  text: analysis  // fallback plain text
};
